-- v16: backward-compatible character builds. No legacy character is rewritten.
-- New class distribution/choices live in characters.system_data; its existing
-- transactional save_character RPC and campaign RLS continue to own all writes.
create table public.dnd_character_build_rules (
 class_id text primary key references public.dnd_classes(id), data jsonb not null
);
create table public.dnd_backgrounds (
 id text primary key, name text not null, data jsonb not null
);
alter table public.dnd_character_build_rules enable row level security;
alter table public.dnd_backgrounds enable row level security;
create policy build_rules_read on public.dnd_character_build_rules for select to authenticated using(true);
create policy backgrounds_read on public.dnd_backgrounds for select to authenticated using(true);
grant select on public.dnd_character_build_rules,public.dnd_backgrounds to authenticated;

insert into public.dnd_character_build_rules values('barbarian',$catalog${"features":[{"id":"furia","level":1,"name":"Fúria","description":"Ação bônus; dura até 1 minuto. Vantagem em testes e salvaguardas de Força, resistência a dano cortante, perfurante e concussão e bônus no dano de ataques corpo a corpo com Força. Sem armadura pesada; impede conjuração e concentração. Bônus +2, +3 no nível 9 e +4 no 16."},{"id":"defesa-sem-armadura","level":1,"name":"Defesa sem armadura","description":"Sem armadura, CA = 10 + DES + CON; escudo permitido. Em multiclasse, outra Defesa sem Armadura não é adquirida novamente."},{"id":"ataque-descuidado","level":2,"name":"Ataque descuidado","description":"No primeiro ataque do turno, pode dar vantagem aos ataques corpo a corpo com Força deste turno; ataques contra você têm vantagem até seu próximo turno."},{"id":"sentido-de-perigo","level":2,"name":"Sentido de perigo","description":"Vantagem em salvaguardas de Destreza contra efeitos que você vê, se não estiver cego, surdo ou incapacitado."},{"id":"caminho-primitivo","level":3,"name":"Caminho primitivo","description":"Escolha seu caminho; novas habilidades nos níveis 6, 10 e 14."},{"id":"ataque-extra","level":5,"name":"Ataque extra","description":"Dois ataques com a ação Atacar. Não soma com Ataque Extra de outra classe."},{"id":"movimento-rapido","level":5,"name":"Movimento rápido","description":"+3 m de deslocamento enquanto não usa armadura pesada."},{"id":"instinto-selvagem","level":7,"name":"Instinto selvagem","description":"Vantagem na iniciativa; pode agir surpreendido se entrar em fúria antes de agir."},{"id":"critico-brutal","level":9,"name":"Crítico brutal","description":"Um dado adicional da arma em críticos corpo a corpo; dois no nível 13, três no 17."},{"id":"furia-implacavel","level":11,"name":"Fúria implacável","description":"Se chegar a 0 PV em fúria sem morrer, salvaguarda de CON CD 10 para ficar com 1 PV. CD sobe 5 a cada uso; reinicia em descanso curto ou longo."},{"id":"furia-persistente","level":15,"name":"Fúria persistente","description":"A fúria termina antecipadamente apenas se você ficar inconsciente ou a encerrar."},{"id":"forca-indomavel","level":18,"name":"Força indomável","description":"Se um teste de Força ficar abaixo de seu valor de Força, use o valor do atributo."},{"id":"campeao-primitivo","level":20,"name":"Campeão primitivo","description":"FOR e CON aumentam em 4; seus limites passam a 24. A ficha aplica esse aumento às fichas com atributos gerados."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"barbarian","id":"berserker","name":"Berserker","features":[{"id":"frenesi","level":3,"name":"Frenesi","description":"Ao entrar em fúria, pode fazer frenesi: a partir dos próximos turnos, um ataque corpo a corpo como ação bônus. Ao terminar a fúria, ganha um nível de exaustão."},{"id":"furia-irracional","level":6,"name":"Fúria irracional","description":"Não pode ser amedrontado ou enfeitiçado durante a fúria; esses efeitos ficam suspensos."},{"id":"presenca-intimidante","level":10,"name":"Presença intimidante","description":"Ação: alvo que vê em 9 m faz SAB, CD 8 + proficiência + CAR, ou fica amedrontado até fim do próximo turno. Pode prolongar com ações; sucesso protege por 24 horas."},{"id":"retaliacao","level":14,"name":"Retaliação","description":"Reação: ao sofrer dano de criatura em 1,5 m, pode fazer um ataque corpo a corpo contra ela."}],"level":3,"source":"SRD 5.1"}],"training":{"count":2,"skills":["animal_handling","athletics","intimidation","nature","perception","survival"],"initial":["Armaduras leves e médias","Escudos","Armas simples e marciais"],"multi":["Escudos","Armas simples e marciais"]},"requirements":[["str"]],"subclass_level":3,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{},"berserker:1:initial":{},"berserker:1:multi":{},"berserker:2:initial":{},"berserker:2:multi":{},"berserker:3:initial":{},"berserker:3:multi":{},"berserker:4:initial":{},"berserker:4:multi":{},"berserker:5:initial":{},"berserker:5:multi":{},"berserker:6:initial":{},"berserker:6:multi":{},"berserker:7:initial":{},"berserker:7:multi":{},"berserker:8:initial":{},"berserker:8:multi":{},"berserker:9:initial":{},"berserker:9:multi":{},"berserker:10:initial":{},"berserker:10:multi":{},"berserker:11:initial":{},"berserker:11:multi":{},"berserker:12:initial":{},"berserker:12:multi":{},"berserker:13:initial":{},"berserker:13:multi":{},"berserker:14:initial":{},"berserker:14:multi":{},"berserker:15:initial":{},"berserker:15:multi":{},"berserker:16:initial":{},"berserker:16:multi":{},"berserker:17:initial":{},"berserker:17:multi":{},"berserker:18:initial":{},"berserker:18:multi":{},"berserker:19:initial":{},"berserker:19:multi":{},"berserker:20:initial":{},"berserker:20:multi":{}},"path_spells":{}}$catalog$::jsonb);
insert into public.dnd_character_build_rules values('bard',$catalog${"features":[{"id":"conjuracao","level":1,"name":"Conjuração","description":"Carisma; magias conhecidas, rituais conhecidos e foco musical. Cada classe mantém sua própria seleção de magias."},{"id":"inspiracao-de-bardo","level":1,"name":"Inspiração de bardo","description":"Ação bônus para inspirar outra criatura que ouve você em 18 m. Dado d6 em até 10 minutos para teste, ataque ou salvaguarda; d8 no nível 5, d10 no 10, d12 no 15. Usos = CAR (mínimo 1)."},{"id":"versatilidade","level":2,"name":"Versatilidade","description":"Metade da proficiência, arredondada para baixo, em testes sem proficiência; inclui iniciativa."},{"id":"cancao-de-descanso","level":2,"name":"Canção de descanso","description":"Ao recuperar PV com Dados de Vida num descanso curto, aliados que ouvem você recuperam +1d6; d8 no nível 9, d10 no 13, d12 no 17."},{"id":"colegio-de-bardo","level":3,"name":"Colégio de bardo","description":"Escolha seu colégio; benefícios nos níveis 6 e 14."},{"id":"especializacao","level":3,"name":"Especialização","description":"Escolha duas perícias em que é proficiente para dobrar o bônus de proficiência. Mais duas no nível 10."},{"id":"fonte-de-inspiracao","level":5,"name":"Fonte de inspiração","description":"Inspirações passam a recuperar em descanso curto ou longo."},{"id":"contrafeitico","level":6,"name":"Contrafeitiço","description":"Ação: até o fim do próximo turno, aliados em 9 m que ouvem você têm vantagem contra medo e encantamento."},{"id":"segredos-magicos","level":10,"name":"Segredos mágicos","description":"Escolha duas magias de qualquer classe até seu círculo de bardo; contam no limite de conhecidas. Mais duas nos níveis 14 e 18."},{"id":"inspiracao-superior","level":20,"name":"Inspiração superior","description":"Ao rolar iniciativa sem inspirações restantes, recupera um uso."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"bard","id":"lore","name":"Colégio do Conhecimento","features":[{"id":"pericias-adicionais","level":3,"name":"Perícias adicionais","description":"Escolha três novas perícias."},{"id":"palavras-cortantes","level":3,"name":"Palavras cortantes","description":"Reação e inspiração: reduz ataque, teste ou dano de criatura que ouve você em 18 m. Não afeta imunes a encantamento."},{"id":"segredos-magicos-adicionais","level":6,"name":"Segredos mágicos adicionais","description":"Duas magias de qualquer classe até seu círculo de bardo, fora do limite de conhecidas; registre-as como extras."},{"id":"pericia-inigualavel","level":14,"name":"Perícia inigualável","description":"Pode gastar inspiração em seu próprio teste de atributo após rolar, antes do resultado."}],"level":3,"source":"SRD 5.1"}],"training":{"count":3,"skills":["acrobatics","animal_handling","arcana","athletics",