insert into public.dnd_character_build_rules values('cleric',$catalog${"features":[{"id":"conjuracao","level":1,"name":"Conjuração","description":"Sabedoria; prepara nível de clérigo + SAB magias (mínimo 1). Magias de domínio ficam sempre preparadas e não contam nesse limite. Rituais preparados."},{"id":"dominio-divino","level":1,"name":"Domínio divino","description":"Escolha o domínio; habilidades nos níveis 1, 2, 6, 8 e 17."},{"id":"canalizar-divindade","level":2,"name":"Canalizar divindade","description":"Uma reserva compartilhada com paladino: um uso, dois no nível 6, três no 18; recupera em descanso curto ou longo. Escolha Expulsar Mortos-Vivos ou o efeito do domínio."},{"id":"expulsar-mortos-vivos","level":2,"name":"Expulsar mortos-vivos","description":"Ação, símbolo sagrado: mortos-vivos em 9 m que veem ou ouvem você fazem salvaguarda de SAB contra sua CD de clérigo; falha os expulsa por 1 minuto ou até sofrerem dano."},{"id":"destruir-mortos-vivos","level":5,"name":"Destruir mortos-vivos","description":"Ao falharem contra Expulsar, mortos-vivos até ND 1/2 são destruídos; ND 1 no nível 8, 2 no 11, 3 no 14, 4 no 17."},{"id":"intervencao-divina","level":10,"name":"Intervenção divina","description":"Ação: role d100; resultado até seu nível de clérigo recebe intervenção escolhida pelo mestre. Falha recupera em descanso longo; sucesso aguarda 7 dias. No nível 20, sucesso automático."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"cleric","id":"life","name":"Domínio da Vida","features":[{"id":"proficiencia-adicional","level":1,"name":"Proficiência adicional","description":"Ganha proficiência em armaduras pesadas."},{"id":"discipulo-da-vida","level":1,"name":"Discípulo da vida","description":"Magias de cura de 1º círculo ou maior curam +2 + círculo do espaço. A Mesa soma esse bônus ao dano/cura básico quando aplicável."},{"id":"preservar-a-vida","level":2,"name":"Preservar a vida","description":"Canalizar Divindade: distribua 5 × nível de clérigo PV entre criaturas em 9 m, até metade dos PV máximos de cada; não afeta construtos/mortos-vivos."},{"id":"curandeiro-abencoado","level":6,"name":"Curandeiro abençoado","description":"Ao curar outra criatura com magia de 1º círculo ou maior, você recupera 2 + círculo do espaço PV."},{"id":"golpe-divino","level":8,"name":"Golpe divino","description":"Uma vez em seu turno, ataque com arma causa +1d8 radiante; +2d8 no nível 14."},{"id":"cura-suprema","level":17,"name":"Cura suprema","description":"Quando rolar dados para cura de magia, use o máximo dos dados em vez de rolar."}],"level":1,"source":"SRD 5.1"}],"training":{"count":2,"skills":["history","insight","medicine","persuasion","religion"],"initial":["Armaduras leves e médias","Escudos","Armas simples"],"multi":["Armaduras leves e médias","Escudos"]},"requirements":[["wis"]],"subclass_level":1,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{},"life:1:initial":{},"life:1:multi":{},"life:2:initial":{},"life:2:multi":{},"life:3:initial":{},"life:3:multi":{},"life:4:initial":{},"life:4:multi":{},"life:5:initial":{},"life:5:multi":{},"life:6:initial":{},"life:6:multi":{},"life:7:initial":{},"life:7:multi":{},"life:8:initial":{},"life:8:multi":{},"life:9:initial":{},"life:9:multi":{},"life:10:initial":{},"life:10:multi":{},"life:11:initial":{},"life:11:multi":{},"life:12:initial":{},"life:12:multi":{},"life:13:initial":{},"life:13:multi":{},"life:14:initial":{},"life:14:multi":{},"life:15:initial":{},"life:15:multi":{},"life:16:initial":{},"life:16:multi":{},"life:17:initial":{},"life:17:multi":{},"life:18:initial":{},"life:18:multi":{},"life:19:initial":{},"life:19:multi":{},"life:20:initial":{},"life:20:multi":{}},"path_spells":{"life:1:":["Bless","Cure Wounds"],"life:1:Ártico":["Bless","Cure Wounds"],"life:1:Costa":["Bless","Cure Wounds"],"life:1:Deserto":["Bless","Cure Wounds"],"life:1:Floresta":["Bless","Cure Wounds"],"life:1:Montanha":["Bless","Cure Wounds"],"life:1:Pântano":["Bless","Cure Wounds"],"life:1:Planície":["Bless","Cure Wounds"],"life:1:Subterrâneo":["Bless","Cure Wounds"],"life:2:":["Bless","Cure Wounds"],"life:2:Ártico":["Bless","Cure Wounds"],"life:2:Costa":["Bless","Cure Wounds"],"life:2:Deserto":["Bless","Cure Wo