insert into public.dnd_character_build_rules values('druid',$catalog${"features":[{"id":"druidico","level":1,"name":"Druídico","description":"Aprende o idioma secreto Druídico; mensagens ocultas são reconhecidas por druidas."},{"id":"conjuracao","level":1,"name":"Conjuração","description":"Sabedoria; prepara nível de druida + SAB magias (mínimo 1). Rituais preparados. Druidas evitam armaduras e escudos de metal."},{"id":"forma-selvagem","level":2,"name":"Forma selvagem","description":"Ação: assume forma de uma besta já vista por até metade do nível de druida em horas. Dois usos por descanso curto/longo. ND 1/4 sem voo/natação; ND 1/2 com natação no nível 4; ND 1 com voo no nível 8. Regras da forma e PV separados são resolvidas com o mestre."},{"id":"circulo-druidico","level":2,"name":"Círculo druídico","description":"Escolha o círculo; benefícios nos níveis 6, 10 e 14."},{"id":"corpo-atemporal","level":18,"name":"Corpo atemporal","description":"Envelhece um ano a cada dez anos."},{"id":"magias-da-besta","level":18,"name":"Magias da besta","description":"Pode usar componentes verbais e somáticos de magias de druida em Forma Selvagem, com as restrições dos componentes materiais."},{"id":"arquidruida","level":20,"name":"Arquidruida","description":"Forma Selvagem ilimitada; ignora componentes verbais, somáticos e materiais sem custo que não sejam consumidos."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"druid","id":"land","name":"Círculo da Terra","features":[{"id":"truque-adicional","level":2,"name":"Truque adicional","description":"Aprende mais um truque de druida."},{"id":"recuperacao-natural","level":2,"name":"Recuperação natural","description":"Após descanso curto, recupera espaços cuja soma dos círculos não excede metade do nível de druida arredondada para cima, sem círculos 6+. Um uso por descanso longo."},{"id":"magias-de-circulo","level":3,"name":"Magias de círculo","description":"Escolha o ambiente; recebe magias sempre preparadas nos níveis 3, 5, 7 e 9. Registre as magias do ambiente no grimório como extras."},{"id":"caminho-da-floresta","level":6,"name":"Caminho da floresta","description":"Ignora terreno difícil não mágico e vegetação comum; vantagem contra plantas mágicas que impedem movimento."},{"id":"protecao-natural","level":10,"name":"Proteção natural","description":"Imune a veneno/doença; elementais e fadas não podem enfeitiçar ou amedrontar você."},{"id":"santuario-natural","level":14,"name":"Santuário natural","description":"Animais e plantas que o atacam fazem SAB contra sua CD; falha obriga escolher outro alvo ou perder o ataque. A proteção cessa para a criatura se você a atacar."}],"level":2,"source":"SRD 5.1"}],"training":{"count":2,"skills":["arcana","animal_handling","insight","medicine","nature","perception","religion","survival"],"initial":["Armaduras leves e médias não metálicas","Escudos não metálicos","Armas druídicas","Kit de herbalismo"],"multi":["Armaduras leves e médias não metálicas","Escudos não metálicos"]},"requirements":[["wis"]],"subclass_level":2,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{},"land:1:initial":{},"land:1:multi":{},"land:2:initial":{},"land:2:multi":{},"land:3:initial":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},"land:3:multi":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},"land:4:initial":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},"land:4:multi":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},"land:5:initial":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},"land:5:multi":{"land":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"De