insert into public.dnd_character_build_rules values('monk',$catalog${"features":[{"id":"defesa-sem-armadura","level":1,"name":"Defesa sem armadura","description":"CA = 10 + DES + SAB sem armadura ou escudo. Se já possui Defesa sem Armadura de outra classe, não ganha outra fórmula."},{"id":"artes-marciais","level":1,"name":"Artes marciais","description":"Sem armadura/escudo, pode usar DES com ataques desarmados e armas de monge. Dano d4, d6 no nível 5, d8 no 11, d10 no 17; após Atacar, pode fazer um ataque desarmado bônus."},{"id":"ki","level":2,"name":"Ki","description":"Pontos = nível de monge; descanso curto/longo com 30 minutos de meditação. CD de ki = 8 + proficiência + SAB. Rajada de Golpes, Defesa Paciente e Passo do Vento custam 1 ponto e ação bônus."},{"id":"movimento-sem-armadura","level":2,"name":"Movimento sem armadura","description":"Sem armadura/escudo, +3 m; +4,5 no nível 6, +6 no 10, +7,5 no 14, +9 no 18. No nível 9 pode correr por superfícies verticais e líquidos no turno."},{"id":"tradicao-monastica","level":3,"name":"Tradição monástica","description":"Escolha a tradição; habilidades nos níveis 6, 11 e 17."},{"id":"defletir-projeteis","level":3,"name":"Defletir projéteis","description":"Reação: reduz dano de ataque com arma à distância em 1d10 + DES + nível de monge; se reduzir a zero pode apanhar o projétil, e gastar 1 ki para arremessá-lo."},{"id":"queda-lenta","level":4,"name":"Queda lenta","description":"Reação: reduz dano de queda em 5 × nível de monge."},{"id":"ataque-extra","level":5,"name":"Ataque extra","description":"Dois ataques na ação Atacar; não soma com outra classe."},{"id":"ataque-atordoante","level":5,"name":"Ataque atordoante","description":"Ao acertar ataque corpo a corpo com arma, pode gastar 1 ki: alvo faz CON contra CD de ki ou fica atordoado até fim do próximo turno."},{"id":"golpes-de-ki","level":6,"name":"Golpes de ki","description":"Ataques desarmados contam como mágicos para resistência/imunidade."},{"id":"evasao","level":7,"name":"Evasão","description":"Efeitos que permitem DES para metade do dano: sucesso causa zero, falha causa metade."},{"id":"mente-tranquila","level":7,"name":"Mente tranquila","description":"Ação: encerra um efeito que o deixa amedrontado ou enfeitiçado."},{"id":"pureza-corporal","level":10,"name":"Pureza corporal","description":"Imune a doenças e veneno."},{"id":"idioma-do-sol-e-da-lua","level":13,"name":"Idioma do sol e da lua","description":"Entende todos os idiomas falados; criaturas que entendem um idioma entendem você."},{"id":"alma-de-diamante","level":14,"name":"Alma de diamante","description":"Proficiência em todas as salvaguardas; pode gastar 1 ki para repetir uma falha e aceitar o novo resultado."},{"id":"corpo-atemporal","level":15,"name":"Corpo atemporal","description":"Sem fragilidade por idade e sem envelhecimento mágico; dispensa alimento/água, mas ainda pode morrer de velhice."},{"id":"corpo-vazio","level":18,"name":"Corpo vazio","description":"Ação e 4 ki: invisibilidade por 1 minuto e resistência a todos os danos exceto energia. 8 ki para Projeção Astral só em si."},{"id":"eu-perfeito","level":20,"name":"Eu perfeito","description":"Ao rolar iniciativa sem ki restante, recupera 4 pontos."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"monk","id":"open-hand","name":"Caminho da Mão Aberta","features":[{"id":"tecnica-da-mao-aberta","level":3,"name":"Técnica da mão aberta","description":"Ao acertar com Rajada de Golpes, escolha: DES ou caído; FOR ou empurrar 4,5 m; ou impedir reações até fim do seu próximo turno."},{"id":"integridade-corporal","level":6,"name":"Integridade corporal","description":"Ação: cura 3 × nível de monge PV; um uso por descanso longo."},{"id":"tranquilidade","level":11,"name":"Tranquilidade","description":"Ao terminar descanso longo, ganha efeito de Santuário até início do próximo descanso longo; CD 8 + proficiência + SAB, termina se atacar ou afetar inimigo com magia."},{"id":"palma-vibrante","level":17,"name":"Palma vibrante","description":"3 ki após acertar ataque desarmado; duração em dias igual ao nível de monge. Ação para encerrar: alvo faz CON, falha reduz a 0 PV, sucesso causa 10d10 necrótico. Apenas uma criatura marcada."}],"level":3,"source":"SRD 5.1"}],"training":{"count":2,"skills":["acrobatics","athletics","history","insight","religion","stealth"],"initial":["Armas simples e espadas curtas","Uma ferramenta de artesão ou instrumento"],"multi":["Armas simples e espadas curtas"]},"requirements":[["dex"],["wis"]],"subclass_level":3,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{},"open-hand:1:initial":{},"open-hand:1:multi":{},"open-hand:2:initial":{},"open-hand:2:multi":{},"open-hand:3:initial":{},"open-hand:3:multi":{},"open-hand:4:initial":{},"open-hand:4:multi":{},"open-hand:5:initial":{},"open-hand:5:multi":{},"open-hand:6:initial":{},"open-hand:6:multi":{},"open-hand:7:initial":{},"open-hand:7:multi":{},"open-hand:8:initial":{},"open-hand:8:multi":{},"open-hand:9:initial":{},"open-hand:9:multi":{},"open-hand:10:initial":{},"open-hand:10:multi":{},"open-hand:11:initial":{},"open-hand:11:multi":{},"open-hand:12:initial":{},"open-hand:12:multi":{},"open-hand:13:initial":{},"open-hand:13:multi":{},"open-hand:14:initial":{},"open-hand:14:multi":{},"open-hand:15:initial":{},"open-hand:15:multi":{},"open-hand:16:initial":{},"open-hand:16:multi":{},"open-hand:17:initial":{},"open-hand:17:multi":{},"open-hand:18:initial":{},"open-hand:18:multi":{},"open-hand:19:initial":{},"open-hand:19:multi":{},"open-hand:20:initial":{},"open-hand:20:multi":{}},"path_spells":{}}$catalog$::jsonb);
insert into public.dnd_character_build_rules values('paladin',$catalog${"features":[{"id":"sentido-divino","level":1,"name":"Sentido divino","description":"Ação: até fim do próximo turno, detecta localização/tipo de celestiais, ínferos e mortos-vivos em 18 m sem cobertura total, e lugares/objetos consagrados. Usos = 1 + CAR por descanso longo."},{"id":"impor-as-maos","level":1,"name":"Impor as mãos","description":"Reserva de cura = 5 × nível de paladino por descanso longo. Ação e toque para distribuir PV; 5 pontos removem uma doença ou veneno. Sem efeito em construtos/mortos-vivos."},{"id":"estilo-de-luta","level":2,"name":"Estilo de luta","description":"Escolha um estilo permitido para paladino."},{"id":"conjuracao","level":2,"name":"Conjuração","description":"Carisma; prepara metade do nível de paladino arredondada para baixo + CAR magias (mínimo 1). Juramento concede magias sempre preparadas."},{"id":"destruicao-divina","level":2,"name":"Destruição divina","description":"Após acerto corpo a corpo, gaste espaço: +2d8 radiante no 1º círculo, +1d8 por círculo acima até 5d8; +1d8 contra ínferos/mortos-vivos, máximo 6d8. O mestre resolve esse dano adicional."},{"id":"saude-divina","level":3,"name":"Saúde divina","description":"Imune a doenças."},{"id":"juramento-sagrado","level":3,"name":"Juramento sagrado","description":"Escolha o juramento; Canalizar Divindade compartilha reserva com clérigo. Novas habilidades nos níveis 7, 15 e 20."},{"id":"ataque-extra","level":5,"name":"Ataque extra","description":"Dois ataques na ação Atacar; não soma com outra classe."},{"id":"aura-de-protecao","level":6,"name":"Aura de proteção","description":"Você e aliados em 3 m somam CAR (mínimo +1) às salvaguardas enquanto está consciente. Raio 9 m no nível 18."},{"id":"aura-de-coragem","level":10,"name":"Aura de coragem","description":"Você e aliados em 3 m não podem ser amedrontados enquanto está consciente; raio 9 m no nível 18."},{"id":"destruicao-divina-aprimorada","level":11,"name":"Destruição divina aprimorada","description":"Cada acerto corpo a corpo com arma causa +1d8 radiante."},{"id":"toque-purificador","level":14,"name":"Toque purificador","description":"Ação: encerra uma magia em si ou criatura voluntária tocada. CAR usos (mínimo 1) por descanso longo."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"paladin","id":"devotion","name":"Juramento de Devoção","features":[{"id":"arma-sagrada","level":3,"name":"Arma sagrada","description":"Canalizar Divindade: ação, arma por 1 minuto soma CAR (mínimo +1) aos ataques e emite luz; é mágica se não era."},{"id":"expulsar-profanos","level":3,"name":"Expulsar profanos","description":"Canalizar Divindade: ínferos/mortos-vivos em 9 m fazem SAB ou são expulsos por 1 minuto ou até sofrer dano."},{"id":"aura-de-devocao","level":7,"name":"Aura de devoção","description":"Você e aliados em 3 m não podem ser enfeitiçados enquanto está consciente; 9 m no nível 18."},{"id":"pureza-de-espirito","level":15,"name":"Pureza de espírito","description":"Proteção contra o Bem e o Mal sempre ativa em você."},{"id":"aura-sagrada","level":20,"name":"Aura sagrada","description":"Ação: luz em 9 m por 1 minuto; inimigos que começam nessa área sofrem 10 radiante. Vantagem nas salvaguardas contra magias de ínferos/mortos-vivos. Um uso por descanso longo."}],"level":3,"source":"SRD 5.1"}],"training":{"count":2,"skills":["athletics","insight","intimidation","medicine","persuasion","religion"],"initial":["Todas as armaduras","Escudos","Armas simples e marciais"],"multi":["Armaduras leves e médias","Escudos","Armas simples e marciais"]},"requirements":[["str"],["cha"]],"subclass_level":3,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":2:multi":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":3:initial":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":3:multi":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":4:initial":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":4:multi":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":5:initial":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":5:multi":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protection"}]}},":6:initial":{"style":{"count":1,"options":[{"id":"defense"},{"id":"dueling"},{"id":"great-weapon"},{"id":"protec