insert into public.dnd_character_build_rules values('ranger',$catalog${"features":[{"id":"inimigo-favorito","level":1,"name":"Inimigo favorito","description":"Escolha um tipo de criatura ou dois tipos de humanoide e um idioma associado. Vantagem em rastrear e recordar informações sobre esse inimigo. Novas escolhas nos níveis 6 e 14."},{"id":"explorador-natural","level":1,"name":"Explorador natural","description":"Escolha terreno favorito; novas escolhas nos níveis 6 e 10. Em viagens de uma hora ou mais nesse terreno, melhora navegação, coleta e rastreamento, conforme o mestre."},{"id":"estilo-de-luta","level":2,"name":"Estilo de luta","description":"Escolha um estilo permitido para patrulheiro."},{"id":"conjuracao","level":2,"name":"Conjuração","description":"Sabedoria; magias conhecidas conforme seu nível de patrulheiro, independente de níveis em outras classes."},{"id":"arquetipo-de-patrulheiro","level":3,"name":"Arquétipo de patrulheiro","description":"Escolha o arquétipo; benefícios nos níveis 7, 11 e 15."},{"id":"consciencia-primitiva","level":3,"name":"Consciência primitiva","description":"Ação e espaço: por 1 minuto por círculo, sente certos tipos de criatura até 1,5 km, ou 9 km em terreno favorito; não informa localização ou quantidade."},{"id":"ataque-extra","level":5,"name":"Ataque extra","description":"Dois ataques na ação Atacar; não soma com outra classe."},{"id":"caminho-da-floresta","level":8,"name":"Caminho da floresta","description":"Ignora custo de terreno difícil não mágico e vegetação não mágica; vantagem contra plantas criadas/manipuladas por magia para impedir movimento."},{"id":"mimetismo","level":10,"name":"Mimetismo","description":"Após 1 minuto preparando camuflagem, +10 em Furtividade parado contra superfície sólida larga; agir/mover-se exige preparar novamente."},{"id":"desaparecer","level":14,"name":"Desaparecer","description":"Esconder como ação bônus; não pode ser rastreado por meios não mágicos salvo se deixar pistas voluntariamente."},{"id":"sentidos-selvagens","level":18,"name":"Sentidos selvagens","description":"Sem desvantagem em ataques contra alvos que não vê; conhece posição de invisíveis em 9 m se não estiver escondidos e você não estiver cego/surdo."},{"id":"matador-de-inimigos","level":20,"name":"Matador de inimigos","description":"Uma vez por turno, soma SAB a ataque ou dano contra inimigo favorito, após rolar mas antes de aplicar o resultado."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"ranger","id":"hunter","name":"Caçador","features":[{"id":"presa-do-cacador","level":3,"name":"Presa do caçador","description":"Escolha Matador de Colossos, Assassino de Gigantes ou Destruidor de Hordas."},{"id":"taticas-defensivas","level":7,"name":"Táticas defensivas","description":"Escolha Fugir da Horda, Defesa contra Multiataque ou Vontade de Aço."},{"id":"multiataque","level":11,"name":"Multiataque","description":"Escolha Saraivada ou Ataque Giratório."},{"id":"defesa-superior","level":15,"name":"Defesa superior","description":"Escolha Evasão, Manter-se Firme ou Esquiva Sobrenatural."}],"level":3,"source":"SRD 5.1"}],"training":{"count":3,"skills":["animal_handling","athletics","insight","investigation","nature","perception","stealth","survival"],"initial":["Armaduras leves e médias","Escudos","Armas simples e marciais"],"multi":["Armaduras leves e médias","Escudos","Armas simples e marciais","Uma perícia da classe"]},"requirements":[["dex"],["wis"]],"subclass_level":3,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{"enemy-1":{"count":1,"options":[{"id":"Aberrações"},{"id":"Bestas"},{"id":"Celestiais"},{"id":"Construtos"},{"id":"Corruptores"},{"id":"Dragões"},{"id":"Elementais"},{"id":"Fadas"},{"id":"Gigantes"},{"id":"Limos"},{"id":"Monstruosidades"},{"id":"Mortos-vivos"},{"id":"Dois tipos de humanoide (anote na História)"}]},"terrain-1":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},":1:multi":{"multiclass-skill":{"count":1,"options":[{"id":"animal_handling"},{"id":"athletics"},{"id":"insight"},{"id":"investigation"},{"id":"nature"},{"id":"perception"},{"id":"stealth"},{"id":"survival"}],"skills":true},"enemy-1":{"count":1,"options":[{"id":"Aberrações"},{"id":"Bestas"},{"id":"Celestiais"},{"id":"Construtos"},{"id":"Corruptores"},{"id":"Dragões"},{"id":"Elementais"},{"id":"Fadas"},{"id":"Gigantes"},{"id":"Limos"},{"id":"Monstruosidades"},{"id":"Mortos-vivos"},{"id":"Dois tipos de humanoide (anote na História)"}]},"terrain-1":{"count":1,"options":[{"id":"Ártico"},{"id":"Costa"},{"id":"Deserto"},{"id":"Floresta"},{"id":"Montanha"},{"id":"Pântano"},{"id":"Planície"},{"id":"Subterrâneo"}]}},":2:initial":{"style":{"count":1,"options":[{"id":"archery"},{"id":"defense"},{"i