insert into public.dnd_character_build_rules values('rogue',$catalog${"features":[{"id":"especializacao","level":1,"name":"Especialização","description":"Escolha duas perícias proficientes, ou uma perícia e ferramentas de ladrão, para dobrar proficiência. Mais duas escolhas no nível 6."},{"id":"ataque-furtivo","level":1,"name":"Ataque furtivo","description":"Uma vez por turno, +1d6 por dois níveis de ladino arredondados para cima, com arma de acuidade/à distância. Requer vantagem ou aliado junto ao alvo e sem desvantagem; o mestre verifica condições."},{"id":"giria-de-ladroes","level":1,"name":"Gíria de ladrões","description":"Aprende linguagem secreta de ladrões, mensagens e sinais."},{"id":"acao-ardilosa","level":2,"name":"Ação ardilosa","description":"Pode Disparar, Desengajar ou Esconder como ação bônus; Disparar/Desengajar estão disponíveis na Mesa."},{"id":"arquetipo-de-ladino","level":3,"name":"Arquétipo de ladino","description":"Escolha seu arquétipo; habilidades nos níveis 9, 13 e 17."},{"id":"esquiva-sobrenatural","level":5,"name":"Esquiva sobrenatural","description":"Reação ao ser acertado por atacante que vê: reduz pela metade o dano desse ataque."},{"id":"evasao","level":7,"name":"Evasão","description":"Salvaguarda de DES para metade: sucesso causa zero e falha causa metade."},{"id":"talento-confiavel","level":11,"name":"Talento confiável","description":"Testes com proficiência tratam d20 de 9 ou menos como 10."},{"id":"sentido-cego","level":14,"name":"Sentido cego","description":"Se pode ouvir, percebe criaturas escondidas/invisíveis a 3 m."},{"id":"mente-escorregadia","level":15,"name":"Mente escorregadia","description":"Ganha proficiência em salvaguardas de Sabedoria."},{"id":"elusivo","level":18,"name":"Elusivo","description":"Nenhum ataque tem vantagem contra você enquanto não está incapacitado."},{"id":"golpe-de-sorte","level":20,"name":"Golpe de sorte","description":"Transforme ataque perdido em acerto ou teste falho em d20 de 20; um uso por descanso curto/longo."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":10,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"rogue","id":"thief","name":"Ladrão","features":[{"id":"maos-rapidas","level":3,"name":"Mãos rápidas","description":"Ação Ardilosa também permite Prestidigitação, ferramentas de ladrão para armadilhas/fechaduras, ou Usar um Objeto."},{"id":"trabalho-no-segundo-andar","level":3,"name":"Trabalho no segundo andar","description":"Escalar não custa movimento adicional; salto longo aumenta em 0,3 × DES metros."},{"id":"furtividade-suprema","level":9,"name":"Furtividade suprema","description":"Vantagem e