insert into public.dnd_character_build_rules values('sorcerer',$catalog${"features":[{"id":"conjuracao","level":1,"name":"Conjuração","description":"Carisma; magias conhecidas e foco arcano. Sua lista e seus limites usam apenas seu nível de feiticeiro."},{"id":"origem-de-feiticaria","level":1,"name":"Origem de feitiçaria","description":"Escolha a origem; habilidades nos níveis 6, 14 e 18."},{"id":"fonte-de-magia","level":2,"name":"Fonte de magia","description":"Pontos de feitiçaria = nível de feiticeiro, recuperados em descanso longo. Ação bônus: espaço em pontos iguais ao círculo, ou pontos em espaços até 5º: custos 2, 3, 5, 6 e 7. Espaços criados são temporários e desaparecem no descanso longo; registre concessões especiais com o mestre."},{"id":"metamagia","level":3,"name":"Metamagia","description":"Escolha duas opções; mais uma nos níveis 10 e 17. Em geral uma opção por magia, exceto quando a opção permite combinação."},{"id":"restauracao-feiticeira","level":20,"name":"Restauração feiticeira","description":"Descanso curto recupera 4 pontos de feitiçaria."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"sorcerer","id":"draconic","name":"Linhagem Dracônica","features":[{"id":"ancestral-draconico","level":1,"name":"Ancestral dracônico","description":"Escolha cor/tipo do dragão. Aprende Dracônico; dobra proficiência em testes de CAR para interagir com dragões."},{"id":"resiliencia-draconica","level":1,"name":"Resiliência dracônica","description":"+1 PV por nível de feiticeiro. Sem armadura, CA = 13 + DES; ficha calcula ambos."},{"id":"afinidade-elemental","level":6,"name":"Afinidade elemental","description":"Ao lançar magia com dano do tipo do ancestral, soma CAR a uma rolagem de dano; pode gastar 1 ponto para resistência ao tipo por 1 hora."},{"id":"asas-de-dragao","level":14,"name":"Asas de dragão","description":"Ação bônus para criar/recolher asas; voo igual ao deslocamento, roupa/armadura deve acomodar asas."},{"id":"presenca-draconica","level":18,"name":"Presença dracônica","description":"Ação e 5 pontos: por 1 minuto, concentração, aura 18 m. SAB contra CD de feiticeiro ou encantado/amedrontado (escolha); sucesso protege por 24 horas."}],"level":1,"source":"SRD 5.1"}],"training":{"count":2,"skills":["arcana","deception","insight","intimidation","persuasion","religion"],"initial":["Adagas, dardos, fundas, bordões e bestas leves"],"multi":[]},"requirements":[["cha"]],"subclass_level":1,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{"metamagic":{"count":2,"options":[{"id":"careful"},{"id":"distant"},{"id":"empowered"},{"id":"extended"},{"id":"heightened"},{"id":"quickened"},{"id":"subtle"},{"id":"twinned"}]}},":3:multi":{"metamagic":{"count":2,"options":[{"id":"careful"},{"id":"distant"},{"id"