insert into public.dnd_character_build_rules values('warlock',$catalog${"features":[{"id":"patrono-transcendental","level":1,"name":"Patrono transcendental","description":"Escolha o patrono; habilidades nos níveis 6, 10 e 14. Magias ampliadas entram na lista, não são aprendidas automaticamente."},{"id":"magia-de-pacto","level":1,"name":"Magia de pacto","description":"Carisma; espaços separados recuperam em descanso curto ou longo. Arcanos Místicos não usam espaços. Em multiclasse, pacto e espaços comuns podem conjurar magias conhecidas/preparadas das outras classes."},{"id":"invocacoes-misticas","level":2,"name":"Invocações místicas","description":"Escolha duas invocações; total 3 no nível 5, 4 no 7, 5 no 9, 6 no 12, 7 no 15, 8 no 18. Requisitos de nível usam nível de bruxo."},{"id":"dadiva-do-pacto","level":3,"name":"Dádiva do pacto","description":"Escolha Corrente, Lâmina ou Tomo. Magias e escolhas extras são registradas no grimório como extras."},{"id":"arcano-mistico","level":11,"name":"Arcano místico","description":"Escolha uma magia de 6º círculo; uma de 7º no nível 13, 8º no 15, 9º no 17. Cada uma tem um uso por descanso longo."},{"id":"mestre-mistico","level":20,"name":"Mestre místico","description":"Uma vez por descanso longo, 1 minuto pedindo ajuda ao patrono recupera todos os espaços de pacto."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"warlock","id":"fiend","name":"O Ínfero","features":[{"id":"bencao-do-infero","level":1,"name":"Bênção do ínfero","description":"Quando reduz hostil a 0 PV, recebe PV temporários = CAR + nível de bruxo (mínimo 1); não acumula com outros PV temporários."},{"id":"sorte-do-proprio-obscuro","level":6,"name":"Sorte do próprio obscuro","description":"Adicione 1d10 a teste de atributo ou salvaguarda após rolar, antes do resultado. Um uso por descanso curto/longo."},{"id":"resistencia-infera","level":10,"name":"Resistência ínfera","description":"Escolha um tipo de dano após descanso curto/longo; resistência, exceto dano de armas mágicas/prateadas."},{"id":"lancar-no-inferno","level":14,"name":"Lançar no inferno","description":"Após acertar ataque, transporta alvo até fim do próximo turno; se não for ínfero sofre 10d10 psíquico. Um uso por descanso longo."}],"level":1,"source":"SRD 5.1"}],"training":{"count":2,"skills":["arcana","deception","history","intimidation","investigation","nature","religion"],"initial":["Armaduras leves","Armas simples"],"multi":["Armaduras leves","Armas simples"]},"requirements":[["cha"]],"subclass_level":1,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{"invocations":{"count":2,"options":[{"id":"agonizing-blast"},{"id":"armor-shadows"},{"id":"beast-speech"},{"id":"beguiling"},{"id":"devil-sight"},{"id":"eldritch-sight"},{"id":"eldritch-spear"},{"id":"eyes-rune"