insert into public.dnd_character_build_rules values('wizard',$catalog${"features":[{"id":"conjuracao","level":1,"name":"Conjuração","description":"Inteligência; começa com seis magias de 1º círculo no livro e aprende duas por nível de mago. Prepara nível de mago + INT (mínimo 1); rituais do livro não precisam estar preparados."},{"id":"recuperacao-arcana","level":1,"name":"Recuperação arcana","description":"Uma vez por dia após descanso curto, recupera espaços com soma dos círculos até metade do nível de mago arredondada para cima; nenhum de 6º ou superior. Escolha quais recuperar no grimório."},{"id":"tradicao-arcana","level":2,"name":"Tradição arcana","description":"Escolha sua tradição; habilidades nos níveis 6, 10 e 14."},{"id":"dominio-de-magias","level":18,"name":"Domínio de magias","description":"Escolha uma magia de 1º e uma de 2º círculo do livro; preparadas, pode conjurá-las em seu círculo básico sem gastar espaço. Círculos superiores ainda gastam espaço."},{"id":"magias-de-assinatura","level":20,"name":"Magias de assinatura","description":"Escolha duas magias de 3º círculo do livro; sempre preparadas, fora do limite, e um uso gratuito de cada por descanso curto/longo."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[{"class_id":"wizard","id":"evocation","name":"Escola de Evocação","features":[{"id":"evocacao-erudita","level":2,"name":"Evocação erudita","description":"Tempo e ouro para copiar magias de evocação no livro são reduzidos à metade."},{"id":"esculpir-magias","level":2,"name":"Esculpir magias","description":"Em evocação que afeta outras criaturas vistas, proteja 1 + círculo da magia criaturas: sucesso automático na salvaguarda e zero dano quando sucesso normalmente daria metade."},{"id":"truque-potente","level":6,"name":"Truque potente","description":"Criatura que passa na salvaguarda de um truque seu ainda recebe metade do dano, sem efeito adicional."},{"id":"evocacao-fortalecida","level":10,"name":"Evocação fortalecida","description":"Soma INT a uma rolagem de dano de magia de evocação de mago."},{"id":"sobrecarga","level":14,"name":"Sobrecarga","description":"Maximiza dano de magia de mago de 1º a 5º círculo. Primeiro uso sem custo por descanso longo; depois sofre 2d12 necrótico por círculo, +1d12 por repetição; não pode reduzir esse dano."}],"level":2,"source":"SRD 5.1"}],"training":{"count":2,"skills":["arcana","history","insight","investigation","medicine","religion"],"initial":["Adagas, dardos, fundas, bordões e bestas leves"],"multi":[]},"requirements":[["int"]],"subclass_level":2,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{},"evocation:1:initial":{},"evocation:1:multi":{},"evocation:2:initial":{},"evocation:2:multi":{},"evocation:3:initial":{},"evocation:3:multi":{},"evocation:4:initial":{},"evocation:4:multi":{},"evocation:5:initial":{},"evocation:5:multi":{},"evocation:6:initial":{},"evocation:6:multi":{},"evocation:7:initial":{},"evocation:7:multi":{},"evocation:8:initial":{},"evocation:8:multi":{},"evocation:9:initial":{},"evocation:9:multi":{},"evocation:10:initial":{},"evocation:10:multi":{},"evocation:11:initial":{},"evocation:11:multi":{},"evocation:12:initial":{},"evocation:12:multi":{},"evocation:13:initial":{},"evocation:13:multi":{},"evocation:14:initial":{},"evocation:14:multi":{},"evocation:15:initial":{},"evocation:15:multi":{},"evocation:16:initial":{},"evocation:16:multi":{},"evocation:17:initial":{},"evocation:17:multi":{},"evocation:18:initial":{},"evocation:18:multi":{},"evocation:19:initial":{},"evocation:19:multi":{},"evocation:20:initial":{},"evocation:20:multi":{}},"path_spells":{}}$catalog$::jsonb);
insert into public.dnd_character_build_rules values('artificer',$catalog${"features":[{"id":"conjuracao-e-engenhos","level":1,"name":"Conjuração e engenhos","description":"Opção de suplemento já existente no catálogo. Usa Inteligência e progressão de espaços de artífice; consulte seu livro de 2014 para aplicar habilidades e infusões específicas."},{"id":"especialidade-de-artifice","level":3,"name":"Especialidade de artífice","description":"Registre a especialidade personalizada e suas escolhas conforme o livro da mesa. Esta atualização não inclui o texto do suplemento."},{"id":"melhoria-de-atributos","level":4,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":8,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":12,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":16,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."},{"id":"melhoria-de-atributos","level":19,"name":"Melhoria de atributos","description":"Distribua 2 pontos: +2 em um atributo ou +1 em dois. Limite 20; a melhoria pertence ao nível desta classe. Talentos opcionais exigem acordo com o mestre."}],"paths":[],"training":{"count":2,"skills":["arcana","history","investigation","medicine","nature","perception","sleight_of_hand"],"initial":["Consulte o suplemento da mesa"],"multi":["Consulte o suplemento da mesa"]},"requirements":[["int"]],"subclass_level":3,"asi_levels":[4,8,12,16,19],"choices":{":1:initial":{},":1:multi":{},":2:initial":{},":2:multi":{},":3:initial":{},":3:multi":{},":4:initial":{},":4:multi":{},":5:initial":{},":5:multi":{},":6:initial":{},":6:multi":{},":7:initial":{},":7:multi":{},":8:initial":{},":8:multi":{},":9:initial":{},":9:multi":{},":10:initial":{},":10:multi":{},":11:initial":{},":11:multi":{},":12:initial":{},":12:multi":{},":13:initial":{},":13:multi":{},":14:initial":{},":14:multi":{},":15:initial":{},":15:multi":{},":16:initial":{},":16:multi":{},":17:initial":{},":17:multi":{},":18:initial":{},":18:multi":{},":19:initial":{},":19:multi":{},":20:initial":{},":20:multi":{}},"path_spells":{}}$catalog$::jsonb);
